"""Review 021 acceptance tests (Codex H-155 / H-157) against the hosted project, in throw-away scratch schemas:

* the golden registry (``oracle_sources.json``, generated by the OLD code) seeded as an import writes it: the whole
  ``GET /api/sources`` and every toggle step's view equal the old ones; one event per real change; the
  normalization-only source inserted on its first toggle; an unknown id writes nothing;
* the counters (decision a): a Deal Flow decision votes yield once per real change and credits quality kept /
  researched once per candidate (the imported milestone guard holds); a name-matched Conviction creation earns
  quality kept but no yield, and a later Keep adds the yield vote but no second quality credit;
* the baseline: an imported radar count of 3 plus one counted Radar event reads 4 before a toggle, after it and on a
  second read, while the stored record keeps 3.
"""

from __future__ import annotations

import hashlib
import json
import secrets
from collections.abc import Iterator
from datetime import datetime
from pathlib import Path
from typing import Any

import pytest
from fastapi.testclient import TestClient
from psycopg.types.json import Jsonb

from projectzero.api.app import create_app
from projectzero.core.config import Settings
from projectzero.core.db import connect, transaction
from projectzero.dealflow.candidates import DealFlowStore
from projectzero.ops.db_check import _scratch_sql
from projectzero.ops.parity_ranking import diff

pytestmark = pytest.mark.hosted
GOLDEN: dict[str, Any] = json.loads(
    (Path(__file__).resolve().parents[1] / "fixtures" / "golden_v1" / "oracle_sources.json").read_text(encoding="utf-8")
)
T0 = datetime.fromisoformat(GOLDEN["provenance"]["clock"])


@pytest.fixture(scope="module")
def settings() -> Settings:
    try:
        return Settings.from_env()
    except RuntimeError as exc:
        pytest.skip(str(exc))


@pytest.fixture
def schema(settings: Settings) -> Iterator[str]:
    name = f"pz_itest_{secrets.token_hex(4)}"
    admin = connect(settings.db_url, autocommit=True)
    try:
        admin.execute(_scratch_sql(name).encode())
        yield name
    finally:
        admin.execute(f"drop schema if exists {name} cascade".encode())
        admin.close()


@pytest.fixture
def client(settings: Settings, schema: str) -> Iterator[TestClient]:
    app = create_app(Settings(db_url=settings.db_url, schema=schema))
    app.state.clock = lambda: T0
    with TestClient(app, base_url="http://127.0.0.1:8177") as c:
        yield c


def _archive(conn: Any, schema: str, path: str, body: Any) -> None:
    raw = json.dumps(body).encode("utf-8")
    conn.execute(f"insert into {schema}.legacy_documents (path, sha256, bytes, raw, parsed) values (%s, %s, %s, %s, %s)"
                 .encode(), (path, hashlib.sha256(raw).hexdigest(), len(raw), raw, Jsonb(body)))  # fmt: skip


def seed(settings: Settings, schema: str, docs: dict[str, Any]) -> None:
    """The registry as the import writes it (``legacy`` = the record, the archived order), the ledger and inbox rest."""
    with transaction(settings.db_url) as conn:
        for s in docs["sources.json"]["sources"]:
            conn.execute(f"insert into {schema}.sources (id, name, url, kind, enabled, legacy) values (%s, %s, %s, %s, %s, %s)"
                         .encode(), (s["id"], s["name"], s.get("url"), s["kind"], bool(s.get("enabled")), Jsonb(s)))  # fmt: skip
        _archive(conn, schema, "sources.json", docs["sources.json"])
        if "feedback.json" in docs:
            _archive(conn, schema, "feedback.json", docs["feedback.json"])
            conn.execute(f"insert into {schema}.documents (key, body) values ('feedback.json', %s)".encode(),
                         (Jsonb(docs["feedback.json"]),))  # fmt: skip
        if "inbox.json" in docs:
            rest = {k: v for k, v in docs["inbox.json"].items() if k != "candidates"}
            conn.execute(f"insert into {schema}.documents (key, body) values ('inbox.json#rest', %s)".encode(),
                         (Jsonb(rest),))  # fmt: skip


def count(settings: Settings, schema: str, table: str) -> int:
    with transaction(settings.db_url) as conn:
        row = conn.execute(f"select count(*) from {schema}.{table}".encode()).fetchone()
    assert row is not None
    return int(row[0])


def by_id(view: dict[str, Any]) -> dict[str, dict[str, Any]]:
    return {s["id"]: s for s in view["sources"]}


def test_the_golden_registry_and_toggles_match_the_old_code(
    settings: Settings, schema: str, client: TestClient
) -> None:
    seed(settings, schema, GOLDEN["docs"])
    assert diff(GOLDEN["expected"]["view"], client.get("/api/sources").json()) == []
    for i, (step, old) in enumerate(zip(GOLDEN["steps"], GOLDEN["expected"]["steps"], strict=True)):
        assert client.post("/api/sources/toggle", json=step).json() == old["body"], f"step {i}"
        assert diff(old["view"], client.get("/api/sources").json()) == [], f"step {i}"
    # real changes only: x-healthy off, on; x-off on; ch-epfl-creation off (inserted) = 4 events
    assert count(settings, schema, "source_events") == 4
    with transaction(settings.db_url) as conn:
        row = conn.execute(f"select enabled, attrs->'record'->>'name' from {schema}.sources where id = 'ch-epfl-creation'"
                           .encode()).fetchone()  # fmt: skip
    assert row == (False, "EPFL - startups in creation (official)")


def candidate(settings: Settings, schema: str, cid: str, name: str, **legacy: Any) -> None:
    record = {"id": cid, "name": name, "decision": "new", "discovery_tier": "announcement", **legacy}
    with transaction(settings.db_url) as conn:
        conn.execute(f"insert into {schema}.candidates (id, name, status, legacy) values (%s, %s, 'new', %s)".encode(),
                     (cid, name, Jsonb(record)))  # fmt: skip
        _archive_inbox(conn, schema, cid)


def _archive_inbox(conn: Any, schema: str, cid: str) -> None:
    conn.execute(f"insert into {schema}.candidate_aliases (namespace, alias_id, candidate_id) values ('candidate', %s, %s) "
                 "on conflict do nothing".encode(), (cid, cid))  # fmt: skip


def decide(settings: Settings, schema: str, cid: str, status: str, client: TestClient | None = None) -> None:
    """A Deal Flow decision; a Keep goes through the scored Conviction workflow (the real path)."""
    if status == "kept":
        assert client is not None
        r = client.post("/api/conviction/save", json={"company": f"Kept {cid}", "inbox_id": cid,
                                                       "scores": {"founder": 10}})  # fmt: skip
        assert r.status_code in (200, 409), r.text
        return
    with transaction(settings.db_url) as conn:
        DealFlowStore(conn, schema).decide(cid, status, reason="e2e")


def test_decisions_vote_yield_once_per_change_and_credit_quality_once(
    settings: Settings, schema: str, client: TestClient
) -> None:
    seed(settings, schema, {"sources.json": {"sources": [
        {"id": "src-a", "name": "Source A", "kind": "rss", "reliability": "low", "geo": ["DACH"], "sectors": ["ai_sw"],
         "enabled": True, "quality": {"kept": 5}, "yield": {"kept": 2, "research": 0, "rejected": 0}},
        {"id": "src-q", "name": "Source Q", "kind": "api", "reliability": "high", "geo": ["DACH"], "sectors": ["ai_sw"],
         "enabled": True}]}})  # fmt: skip
    candidate(settings, schema, "aa0000000001", "Alpha Example", source_id="src-a", quality_source_id="src-q")
    candidate(settings, schema, "aa0000000002", "Beta Example", source_id="src-a", q_milestones=["kept"])
    decide(settings, schema, "aa0000000001", "kept", client)  # a Keep: yield vote, quality credit
    decide(settings, schema, "aa0000000001", "kept", client)  # the same Keep again: no vote, no credit
    decide(settings, schema, "aa0000000002", "reviewing")  # research: a vote, and a researched credit
    decide(settings, schema, "aa0000000002", "reviewing")  # the same decision again: no vote
    decide(settings, schema, "aa0000000002", "new")
    decide(settings, schema, "aa0000000002", "reviewing")  # a real change again: a vote, but no second credit
    decide(settings, schema, "aa0000000002", "rejected")
    decide(settings, schema, "aa0000000002", "kept", client)  # Keep: a vote; quality was credited before the import
    s = by_id(client.get("/api/sources").json())
    assert s["src-a"]["yield"] == {"kept": 2 + 2, "research": 2, "rejected": 1}
    assert s["src-a"]["quality"]["kept"] == 5 and s["src-a"]["quality"]["researched"] == 1
    assert s["src-q"]["quality"]["kept"] == 1  # alpha's quality source, once


def test_a_name_matched_creation_earns_quality_but_no_yield(
    settings: Settings, schema: str, client: TestClient
) -> None:
    seed(settings, schema, {"sources.json": {"sources": [
        {"id": "src-n", "name": "Source N", "kind": "rss", "reliability": "low", "geo": ["DACH"], "sectors": ["ai_sw"],
         "enabled": True}]}})  # fmt: skip
    candidate(settings, schema, "bb0000000001", "Namematch Robotics", source_id="src-n")
    r = client.post("/api/conviction/save", json={"company": "Namematch Robotics GmbH", "scores": {"founder": 10}})
    assert r.status_code == 200, r.text
    s = by_id(client.get("/api/sources").json())["src-n"]
    assert s["quality"]["kept"] == 1 and "yield" not in s  # no vote: the source never had a yield block
    decide(settings, schema, "bb0000000001", "kept", client)  # the later explicit Keep
    s = by_id(client.get("/api/sources").json())["src-n"]
    assert s["quality"]["kept"] == 1 and s["yield"]["kept"] == 1


def test_a_later_keep_with_another_source_does_not_take_the_creations_credit(
    settings: Settings, schema: str, client: TestClient
) -> None:
    """Codex H-159, end to end: the name-matched creation records source A; the candidate then names source B (a
    re-report changed its provenance); the explicit Keep votes yield but the quality credit stays with A."""
    seed(settings, schema, {"sources.json": {"sources": [
        {"id": s_id, "name": f"Source {s_id}", "kind": "rss", "reliability": "low", "geo": ["DACH"], "sectors": ["ai_sw"],
         "enabled": True, "yield": {"kept": 0, "research": 0, "rejected": 0}} for s_id in ("src-a", "src-b")]}})  # fmt: skip
    candidate(settings, schema, "cc0000000001", "Ordered Robotics", source_id="src-a", quality_source_id="src-a")
    r = client.post("/api/conviction/save", json={"company": "Ordered Robotics GmbH", "scores": {"founder": 10}})
    assert r.status_code == 200, r.text
    with transaction(settings.db_url) as conn:
        conn.execute(f"update {schema}.candidates set legacy = legacy || %s where id = 'cc0000000001'".encode(),
                     (Jsonb({"source_id": "src-b", "quality_source_id": "src-b"}),))  # fmt: skip
    # the explicit Keep: its own linked entry (the name-matched one only recorded provenance, review 011 H-074)
    r = client.post("/api/conviction/save", json={"company": "Ordered Robotics Holding", "inbox_id": "cc0000000001",
                                                  "scores": {"founder": 10}})  # fmt: skip
    assert r.status_code == 200, r.text
    s = by_id(client.get("/api/sources").json())
    assert s["src-a"]["quality"]["kept"] == 1 and s["src-b"]["quality"]["kept"] == 0
    assert s["src-b"]["yield"]["kept"] == 1 and s["src-a"]["yield"]["kept"] == 0


def test_a_provenance_change_after_the_decision_never_moves_its_vote_or_credit(
    settings: Settings, schema: str, client: TestClient
) -> None:
    """Codex H-161: a Research decision and a Conviction Keep made under source A; a re-report then changes the
    candidates' provenance to B; two later reads leave every earned vote and credit with A."""
    seed(settings, schema, {"sources.json": {"sources": [
        {"id": s_id, "name": f"Source {s_id}", "kind": "rss", "reliability": "low", "geo": ["DACH"], "sectors": ["ai_sw"],
         "enabled": True, "yield": {"kept": 0, "research": 0, "rejected": 0}} for s_id in ("src-a", "src-b")]}})  # fmt: skip
    candidate(settings, schema, "dd0000000001", "Researched Example", source_id="src-a")
    candidate(settings, schema, "dd0000000002", "Kept Example", source_id="src-a")
    decide(settings, schema, "dd0000000001", "reviewing")
    decide(settings, schema, "dd0000000002", "kept", client)
    with transaction(settings.db_url) as conn:
        conn.execute(f"update {schema}.candidates set legacy = legacy || %s where id in ('dd0000000001', 'dd0000000002')"
                     .encode(), (Jsonb({"source_id": "src-b", "quality_source_id": "src-b"}),))  # fmt: skip
    for _ in range(2):
        s = by_id(client.get("/api/sources").json())
        assert s["src-a"]["yield"] == {"kept": 1, "research": 1, "rejected": 0}
        assert (s["src-a"]["quality"]["kept"], s["src-a"]["quality"]["researched"]) == (1, 1)
        assert s["src-b"]["yield"] == {"kept": 0, "research": 0, "rejected": 0}
        assert (s["src-b"]["quality"]["kept"], s["src-b"]["quality"]["researched"]) == (0, 0)


def test_a_toggle_keeps_the_baseline(settings: Settings, schema: str, client: TestClient) -> None:
    seed(settings, schema, {"sources.json": {"sources": [
        {"id": "src-r", "name": "Source R", "kind": "api", "reliability": "high", "geo": ["DACH"], "sectors": ["ai_sw"],
         "enabled": True, "quality": {"radar": 3}}]}})  # fmt: skip
    with transaction(settings.db_url) as conn:
        co = conn.execute(
            f"insert into {schema}.companies (name) values ('Radared Co') returning id".encode()
        ).fetchone()
        assert co is not None
        entry = conn.execute(f"insert into {schema}.conviction_entries (company_id, slug, status) values (%s, 'radared', 'new') "
                             "returning id".encode(), (co[0],)).fetchone()  # fmt: skip
        assert entry is not None
        conn.execute(f"insert into {schema}.conviction_events (entry_id, slug, actor, action, after, detail) values "
                     "(%s, 'radared', 'system', 'radar_milestone', '{}', %s)".encode(),
                     (entry[0], Jsonb({"source_id": "src-r", "legacy_credit": False, "counted": True})))  # fmt: skip

    def radar() -> int:
        return int(by_id(client.get("/api/sources").json())["src-r"]["quality"]["radar"])

    assert radar() == 4
    client.post("/api/sources/toggle", json={"id": "src-r", "enabled": False})
    assert radar() == 4
    assert radar() == 4
    with transaction(settings.db_url) as conn:
        stored = conn.execute(f"select attrs->'record'->'quality'->'radar' from {schema}.sources where id = 'src-r'"
                              .encode()).fetchone()  # fmt: skip
    assert stored == (3,)


def test_writes_are_closed_before_the_import_in_production(settings: Settings) -> None:
    app = create_app(Settings(db_url=settings.db_url, schema="pz"))
    with TestClient(app, base_url="http://127.0.0.1:8177") as c:
        r = c.post("/api/sources/toggle", json={"id": "anything", "enabled": False})
    if r.status_code == 409:
        assert "after the legacy import" in r.json()["error"]
    else:  # the live import has happened: the boundary is open (an unknown id is the old no-op)
        assert r.json() == {"ok": True}
